from qgis.PyQt.QtWidgets import QAction, QToolBar, QWidget
mw = iface.mainWindow()
a = None
for x in mw.findChildren(QAction):
    if x.objectName() == 'mDestinationLayerButtonAction':
        a = x
        break
p = a.parent()
chain = []
while p is not None:
    chain.append(type(p).__name__ + '(' + (p.objectName() or '') + ')')
    p = p.parent()
# toolbar it belongs to
bars = []
for tb in mw.findChildren(QToolBar):
    if a in tb.actions():
        bars.append(tb.objectName() or tb.windowTitle())
# widget action? check default widget
info = {'parent_chain': chain, 'toolbars': bars,
        'icon_null': a.icon().isNull(), 'whatsThis': a.whatsThis(), 'statusTip': a.statusTip()}
result = info
"}

