from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
a = None
tb = None
for x in mw.findChildren(QAction):
    if x.objectName() == 'mDestinationLayerButtonAction':
        a = x
        break
for t in mw.findChildren(QToolBar):
    if t.objectName() == 'mGpsToolBar':
        tb = t
        break
w = tb.widgetForAction(a)
info = {'widget': type(w).__name__ + '(' + (w.objectName() or '') + ')' if w else None}
if w is not None:
    for prop in ('text','toolTip','popupMode','checked'):
        try:
            info[prop] = getattr(w, prop)() if callable(getattr(w, prop)) else getattr(w, prop)
        except Exception:
            try: info[prop] = getattr(w, prop)
            except Exception: pass
    try: info['icon_null'] = w.icon().isNull()
    except Exception: pass
# also look at toolbar actions order to locate it
order = [(x.objectName() or x.text()) for x in tb.actions()]
info['toolbar_actions'] = order
result = info
"}

