from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
a = None
for x in mw.findChildren(QAction):
    if x.objectName() == 'mDestinationLayerButtonAction':
        a = x
        break
tb = None
for t in mw.findChildren(QToolBar):
    if t.objectName() == 'mGpsToolBar':
        tb = t
        break
w = tb.widgetForAction(a)
m = w.menu() if hasattr(w,'menu') else None
subs = []
if m is not None:
    try:
        m.aboutToShow.emit()
    except Exception:
        pass
    for s in m.actions():
        subs.append({'text': s.text(), 'enabled': s.isEnabled(), 'checked': s.isChecked() if s.isCheckable() else None, 'icon': not s.icon().isNull()})
result = {'action_enabled': a.isEnabled(), 'button_enabled': w.isEnabled(), 'menu_items': subs}
